#!/bin/sh
# Generated by esquadro: makes your age key (once), writes .sops.yaml with
# it, and adds to secrets/platform.sops.yaml every secret of
# secrets/platform.example.yaml it does not have yet. Values are never
# printed.
set -eu

key="${SOPS_AGE_KEY_FILE:?set SOPS_AGE_KEY_FILE}"
if [ ! -f "$key" ]; then
  mkdir -p "$(dirname "$key")"
  age-keygen -o "$key" 2>/dev/null
  chmod 600 "$key"
  echo "made your age key at $key: keep a copy in your password manager"
fi
recipient=$(age-keygen -y "$key")

if [ ! -f .sops.yaml ]; then
  cat > .sops.yaml <<YAML
# Who can read secrets/: the age keys, one per person.
creation_rules:
  - path_regex: secrets/.*\.sops\.(yaml|env)$
    age: $recipient
YAML
  echo "wrote .sops.yaml"
fi

secrets=secrets/platform.sops.yaml
if [ ! -f "$secrets" ]; then
  echo "{}" | sops encrypt --filename-override "$secrets" --input-type yaml --output-type yaml /dev/stdin > "$secrets"
  echo "created $secrets"
fi

# Each "key: value" line of the example the encrypted file lacks.
grep -E '^[a-z_][a-z0-9_]*:' secrets/platform.example.yaml | while IFS= read -r line; do
  name=${line%%:*}
  value=$(printf '%s' "${line#*:}" | sed 's/^ *//')
  if sops decrypt --extract "[\"$name\"]" "$secrets" >/dev/null 2>&1; then
    continue
  fi
  if [ "$value" = "generate" ]; then
    value=$(head -c 32 /dev/urandom | od -An -tx1 | tr -d ' \n')
    echo "added $name, generated"
  else
    value=""
    echo "added $name: fill it in with task secrets:edit"
  fi
  sops set "$secrets" "[\"$name\"]" "\"$value\""
done
